    if item.get("role") not in roles:
        print(f"trace item {i} has invalid role", file=sys.stderr)
        sys.exit(2)
    if "depends_on" in item:
        print(f"trace item {i} must not contain depends_on", file=sys.stderr)
        sys.exit(2)
